let palette = ['#0045E8', '#51A0FF', '#f33d15', '#f0f0f0', '#EBB62A', '#4ecdc4', '#FF323B'];
let triangleSide;
let triangleHeight;
let gridOrigin;
let triangleCells = [];
let gridWidth;
let walkers = [];
let strokeThickness;

function isInsideCanvas(x, y) {
	return 0 < x && x < width && 0 < y && y < height;
}

function getTriangleStep(w, direction) {
	let r = w / sqrt(3);
	return {
		x: r * cos(direction),
		y: r * sin(direction)
	};
}

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	blendMode(ADD);

	triangleSide = width / 30;
	triangleHeight = triangleSide / 2 * sqrt(3);
	gridOrigin = createVector(-triangleSide, -triangleHeight / 2);
	gridWidth = max(width, height) + triangleSide;
	createTriangleGrid();

	let shapeNum = 100;
	while (shapeNum > 0) {
		let rnd = int(random(triangleCells.length));
		let t = triangleCells[rnd];
		let clr = palette[shapeNum % palette.length];
		if (isInsideCanvas(t.x, t.y)) {
			walkers.push(new TriangleWalker(t.x, t.y, t.a, clr));
			shapeNum--;
		}
	}

	strokeThickness = width / 800;
}

function draw() {
  // === Variant 5: Symmetric Kaleidoscope Portal ===
  // Applying kaleidoscope coordinate distortion
  uM_rot = frameCount * 0.005;
  push();
  translate(width/2, height/2);
  rotate(uM_rot);
  scale(1.1);
  translate(-width/2, -height/2);

	clear();
	background('#000000');
	noFill();
	stroke('#000000');
	strokeWeight(strokeThickness);
	for (let w of walkers) {
		w.run();
	}

  pop();
}

function createTriangleGrid() {
	let seen = new Set();
	let y = gridOrigin.y;
	let yCounter = 0;

	while (y < gridWidth) {
		let xCounter = 0;
		let x = gridOrigin.x;
		let offsetX = yCounter % 2 === 0 ? 0 : -triangleSide / 2;

		while (x < gridWidth) {
			let offsetY = xCounter % 2 === 0 ? 0 : triangleHeight;

			let px = x + offsetX;
			let py = y + offsetY;
			let key = `${px.toFixed(2)}_${py.toFixed(2)}`;

			if (!seen.has(key)) {
				seen.add(key);
				triangleCells.push({
					x: px,
					y: py - (triangleHeight * (2 / 3)),
					a: PI / 2,
				});
				triangleCells.push({
					x: px,
					y: py + (triangleHeight * (2 / 3)),
					a: -PI / 2
				});
			}
			x += triangleSide / 2;
			xCounter++;
		}

		y += triangleHeight;
		yCounter++;

	}
}

function drawTriangle(x, y, w, a) {
	let r = w / sqrt(3);
	beginShape();
	for (let i = 0; i < 3; i++) {
		let ang = a + (TWO_PI / 3) * i;
		let vx = x + r * cos(ang);
		let vy = y + r * sin(ang);
		vertex(vx, vy);
	}
	endShape(CLOSE);
}

