class TriangleWalker {
	constructor(x, y, a, clr) {
		this.x = x;
		this.y = y;
		this.prevX = null;
		this.prevY = null;
		this.w = triangleSide;
		this.angle = a;

		let theta = (int(random(3)) * (TAU / 3)) + this.angle + (TAU / 6);
		let step = getTriangleStep(this.w, theta);
		this.stepX = step.x;
		this.stepY = step.y;

		this.footprints = [];
		this.clr = color(clr);
		this.frameInterval = 2;

		this.shrinkAmount = this.w * 0.01;
	}

	moveToNextInsidePosition() {
		let allCandidates = [];
		for (let i = 0; i < 3; i++) {
			let direction = (i * (TAU / 3)) + this.angle + (TAU / 6);
			let step = getTriangleStep(this.w, direction);
			let nextX = this.x + step.x;
			let nextY = this.y + step.y;
			if (isInsideCanvas(nextX, nextY)) {
				allCandidates.push({ direction, stepX: step.x, stepY: step.y, nextX, nextY });
			}
		}

		let candidates = allCandidates;
		if (this.prevX !== null && this.prevY !== null) {
			candidates = allCandidates.filter(c =>
				abs(c.nextX - this.prevX) > 0.001 || abs(c.nextY - this.prevY) > 0.001
			);
		}

		if (candidates.length === 0) {
			candidates = allCandidates;
		}

		if (candidates.length === 0) {
			return;
		}

		let next = random(candidates);
		this.prevX = this.x;
		this.prevY = this.y;
		this.direction = next.direction;
		this.stepX = next.stepX;
		this.stepY = next.stepY;
		this.x = next.nextX;
		this.y = next.nextY;
		this.angle += PI;
	}

	updateFootprints() {
		for (let f of this.footprints) {
			f.w = max(0, f.w - this.shrinkAmount);
		}

		for (let i = this.footprints.length - 1; i >= 0; i--) {
			if (this.footprints[i].w <= 0) {
				this.footprints.splice(i, 1);
			}
		}
	}

	display() {
		this.clr.setAlpha(100);
		noFill();

		noStroke();
		fill(this.clr);
		drawTriangle(this.x, this.y, this.w, this.angle);
		noFill();
		for (let f of this.footprints) {
			stroke(this.clr);
			this.clr.setAlpha(f.alph);

			drawTriangle(f.x, f.y, f.w, f.a);
		}
	}

	update() {
		if (frameCount % this.frameInterval === 0) {
			this.footprints.push({
				x: this.x,
				y: this.y,
				w: this.w,
				a: this.angle,
				alph: 70
			});
			this.moveToNextInsidePosition();
		}

		this.updateFootprints();

		this.shrinkAmount = this.w * map(cos(frameCount / 90), -1, 1, 0.1, 0.0005);
	}

	run() {
		this.display();
		this.update();
	}
}

